package br.com.inframonitor.auth;
import br.com.inframonitor.auth.dto.*; import br.com.inframonitor.common.api.ErroResposta; import br.com.inframonitor.security.UsuarioPrincipal; import br.com.inframonitor.usuario.dto.UsuarioResponse; import jakarta.servlet.http.HttpServletRequest; import jakarta.validation.Valid; import org.slf4j.Logger; import org.slf4j.LoggerFactory; import org.springframework.http.HttpHeaders; import org.springframework.http.HttpStatus; import org.springframework.http.ResponseEntity; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import java.util.Optional;
/** Login por senha; refresh e logout pelo cookie httpOnly (exigem X-Requested-With, nunca respondem 401). */
@RestController @RequestMapping("/api/v1/auth") public class AuthController { private static final Logger log=LoggerFactory.getLogger(AuthController.class); private static final String XRW="X-Requested-With";
 private final AuthService service; private final SessaoUsuarioService sessoes; private final SessaoCookie cookie;
 public AuthController(AuthService service,SessaoUsuarioService sessoes,SessaoCookie cookie){this.service=service;this.sessoes=sessoes;this.cookie=cookie;}
 /** A sessao nasce depois que a transacao do login comitou; qualquer falha nela devolve o login sem cookie (sessao de 15 min, como antes). */
 @PostMapping("/login") public ResponseEntity<LoginResponse> login(@Valid @RequestBody LoginRequest r){ LoginResponse resp=service.login(r); Optional<SessaoUsuarioService.SessaoCriada> s; try{ s=sessoes.criar(resp.usuario().id()); }catch(RuntimeException e){ log.error("Falha ao criar sessao persistente; login segue sem cookie",e); s=Optional.empty(); } return s.map(x->ResponseEntity.ok().header(HttpHeaders.SET_COOKIE,cookie.emitir(x).toString()).body(resp)).orElseGet(()->ResponseEntity.ok(resp)); }
 @PostMapping("/refresh") public ResponseEntity<?> refresh(@CookieValue(name=SessaoCookie.NOME,required=false) String token,@RequestHeader(name=XRW,required=false) String xrw,HttpServletRequest req){ if(xrw==null||xrw.isBlank())return proibido(req); Optional<Long> id; try{ id=sessoes.validar(token); }catch(SessaoUsuarioService.SessaoIndisponivelException e){ return indisponivel(req); } if(id.isEmpty())return semSessao(); Optional<LoginResponse> resp=service.renovar(id.get()); if(resp.isPresent())return ResponseEntity.ok(resp.get()); sessoes.revogarTodas(id.get()); return semSessao(); }
 @PostMapping("/logout") public ResponseEntity<?> logout(@CookieValue(name=SessaoCookie.NOME,required=false) String token,@RequestHeader(name=XRW,required=false) String xrw,HttpServletRequest req){ if(xrw==null||xrw.isBlank())return proibido(req); sessoes.revogar(token); return semSessao(); }
 @GetMapping("/me") public UsuarioResponse me(@AuthenticationPrincipal UsuarioPrincipal p){return service.me(p.id());}
 private ResponseEntity<?> semSessao(){ return ResponseEntity.noContent().header(HttpHeaders.SET_COOKIE,cookie.apagar().toString()).build(); }
 /** Falha transitoria do banco: 503 sem Set-Cookie. O cookie fica intacto e o proximo refresh (ou F5) restaura a sessao. */
 private ResponseEntity<?> indisponivel(HttpServletRequest req){ return ResponseEntity.status(HttpStatus.SERVICE_UNAVAILABLE).body(ErroResposta.de(503,"Service Unavailable","SERVICE_UNAVAILABLE","Sessao temporariamente indisponivel; tente novamente",req.getRequestURI())); }
 private ResponseEntity<?> proibido(HttpServletRequest req){ return ResponseEntity.status(HttpStatus.FORBIDDEN).body(ErroResposta.de(403,"Forbidden","FORBIDDEN","Cabecalho X-Requested-With obrigatorio",req.getRequestURI())); }
}
